class _PatientShellState extends State<PatientShell> {
  late final controller = PatientController(widget.api ?? ApiClient());
  int tab = 0;
  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  Widget content() {
    final c = controller;
    if (!c.authenticated) {
      return AuthForm(
        auth: c.auth,
        run: c.execute,
        onLogin: c.login,
        onMessage: c.setMessage,
        busy: c.busy,
      );
